import{_ as c,o as g,c as h,ah as p}from"./chunks/framework.GjtxVZ8F.js";const y="/projects/WonderMV/en/latest/assets/image2.CStfF098.png",x="/projects/WonderMV/en/latest/assets/image3.U9B1Tfo7.png",m="/projects/WonderMV/en/latest/assets/image6.CriucXAP.png",u="/projects/WonderMV/en/latest/assets/image7.Da-ifS1T.png",e="/projects/WonderMV/en/latest/assets/1.zhDle6ee.png",n="/projects/WonderMV/en/latest/assets/2.CZ4c5Wiz.png",r="/projects/WonderMV/en/latest/assets/3.CkcxlVtM.png",i="/projects/WonderMV/en/latest/assets/5.C1DxP-QH.png",a="/projects/WonderMV/en/latest/assets/4.DV2c-PPX.png",l="/projects/WonderMV/en/latest/assets/6.BN15D4fO.png",s="/projects/WonderMV/en/latest/assets/7.0EagLByB.png",d="/projects/WonderMV/en/latest/assets/8.0mQ8ImoH.png",o="/projects/WonderMV/en/latest/assets/9.jlIjwxYS.png",f="/projects/WonderMV/en/latest/assets/10.CCNzBTzs.png",_="/projects/WonderMV/en/latest/assets/11.k6RFxAXG.png",I="/projects/WonderMV/en/latest/assets/image4.k27dTx_V.png",w="/projects/WonderMV/en/latest/assets/image2.B7H3q1u7.png",b="/projects/WonderMV/en/latest/assets/image3.Dt-dPj0_.png",C="/projects/WonderMV/en/latest/assets/image4.C8Aq3XxU.png",D="/projects/WonderMV/en/latest/assets/image5.F2hptnyQ.png",P="/projects/WonderMV/en/latest/assets/image2.GTwKt3te.png",O="/projects/WonderMV/en/latest/assets/image3.DV0D_Q9k.png",V="/projects/WonderMV/en/latest/assets/image4.C0vVSdM7.png",S="/projects/WonderMV/en/latest/assets/image5.COKu5Dfg.png",M="/projects/WonderMV/en/latest/assets/image6.CkDIX6I7.png",W=JSON.parse('{"title":"1. Learn K210 Module","description":"","frontmatter":{},"headers":[],"relativePath":"docs/1.learn_K210_Module.md","filePath":"docs/1.learn_K210_Module.md"}'),T={name:"docs/1.learn_K210_Module.md"};function v(R,t,A,k,z,F){return g(),h("div",null,[...t[0]||(t[0]=[p('<h1 id="_1-learn-k210-module" tabindex="-1">1. Learn K210 Module <a class="header-anchor" href="#_1-learn-k210-module" aria-label="Permalink to &quot;1. Learn K210 Module&quot;">​</a></h1><h2 id="_1-1-module-introduction" tabindex="-1">1.1 Module Introduction <a class="header-anchor" href="#_1-1-module-introduction" aria-label="Permalink to &quot;1.1 Module Introduction&quot;">​</a></h2><p><strong>1.1.1 Introduction</strong></p><p>The WonderMV Visual Module is a powerful and cost-effective AI vision module developed based on the K210 chip, hence also referred to as the <strong>&quot;K210 Vision Module&quot;</strong> in the following text.</p><p>It supports 12 AI vision functions, including color recognition, landmark recognition, visual line following, face recognition, mask recognition, tag recognition, QR code recognition, feature detection, number recognition and barcode recognition.</p><p>The WonderMV Visual Module features a metal shell, eliminating the use of cheap acrylic materials. The module is equipped with serial port and IIC communication interfaces, allowing it to be integrated with various control platforms such as STM32, Raspberry Pi, Arduino, 51 single-chip microcontrollers, ESP32, and more. Through the serial port or IIC interface, it outputs visual recognition data to be sent to an external controller. The module supports one-key learning and training, eliminating the need for understanding complex visual algorithms, significantly reducing project development time, and easily realizing various interesting AI projects.</p><p><strong>1.1.2 Front and Back Images</strong></p><img loading="lazy" height="1099" src="'+y+'" class="common_img" width="400px"><p>The front features a 2.0-inch capacitive touchscreen, communicating through I2C, with a resolution of 320*240.</p><img loading="lazy" height="696" src="'+x+'" class="common_img" width="400px"><p>The back is secured with four copper pillars and screws to fix the metal shell in place.</p><p id="anchor_1_1_3"></p><p><strong>1.1.3 Hardware</strong></p><img loading="lazy" height="443" width="580" src="'+m+'" class="common_img"><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Number</strong></th><th style="text-align:center;"><strong>Module</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:center;">User Button</td><td style="text-align:center;">Used as a customizable function button by the user.</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:center;">Fill Light</td><td style="text-align:center;">I/O port controlled fill light, customizable by the user.</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:center;">IIC Interface<br>（SCL、SDA、GND、5V）</td><td style="text-align:center;">Allows communication with other devices using IIC protocol.</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:center;">UART Serial Port&lt;br（TX、RX、GND、5V）</td><td style="text-align:center;">Allows communication with other devices using UART protocol.</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:center;">User LED</td><td style="text-align:center;">I/O port controlled blue LED light, customizable by the user.</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:center;">Power Indicator Light</td><td style="text-align:center;">Indicates whether the onboard power voltage is normal.</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:center;">Power Management Chip</td><td style="text-align:center;">Provides stable voltage for the K210 core board.</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:center;">Camera</td><td style="text-align:center;">2 million pixels parallel camera</td></tr><tr><td style="text-align:center;">9</td><td style="text-align:center;">K210 Chip</td><td style="text-align:center;">Main control chip</td></tr><tr><td style="text-align:center;">10</td><td style="text-align:center;">128Mbit Flash Storage Chip</td><td style="text-align:center;">Stores programs and data.</td></tr><tr><td style="text-align:center;">11</td><td style="text-align:center;">Heat Sink</td><td style="text-align:center;">Ensures the working temperature of the K210 chip and camera.</td></tr><tr><td style="text-align:center;">12</td><td style="text-align:center;">TF Card Slot</td><td style="text-align:center;">Used for external TF card to store data (Recommended to use 32GB, but should not exceed 64GB).</td></tr><tr><td style="text-align:center;">13</td><td style="text-align:center;">Type-C Interface</td><td style="text-align:center;">Power interface (supports 5V/300mA voltage and current), can be used for program download and debugging.</td></tr></tbody></table><p><strong>1.1.4 K210 Vision Module Coordinate System</strong></p><p>The resolution of the touchscreen on the K210 Vision Module is 320*240, and its pixel coordinates have the origin located at the top-left corner of the vision module, as shown in the diagram below:</p><img loading="lazy" height="461" width="650" src="'+u+'" class="common_img"><p><strong>1.1.5 Parameter Explanation</strong></p><p>More parameter details about the K210 Vision Module can be found in the path <a href="./Appendix.html">WonderMV Vision Module-&gt;3. Chip Data &amp; Technical Parameters &amp; AI Model Files-&gt;2. Technical Parameters</a>.</p><h2 id="_1-2-packing-list" tabindex="-1">1.2 Packing List <a class="header-anchor" href="#_1-2-packing-list" aria-label="Permalink to &quot;1.2 Packing List&quot;">​</a></h2><p>(1) WonderMV Vision Module Kit Packing List</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>No.</strong></th><th style="text-align:center;">Component</th><th style="text-align:center;"><strong>Quantity</strong></th><th style="text-align:center;"><strong>Picture</strong></th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:center;">WonderMV vision module</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="78" width="115" src="'+e+'"></td></tr><tr><td style="text-align:center;">2</td><td style="text-align:center;">Type-C data cable (100cm)</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="221" width="1000" src="'+n+'" style="width:200px;"></td></tr><tr><td style="text-align:center;">3</td><td style="text-align:center;">4PIN wire (30cm)</td><td style="text-align:center;">2</td><td style="text-align:center;"><img loading="lazy" height="109" width="485" src="'+r+'" style="width:200px;"></td></tr><tr><td style="text-align:center;">4</td><td style="text-align:center;">32GB SD card</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="283" width="389" src="'+i+'" style="width:45px;"></td></tr><tr><td style="text-align:center;">5</td><td style="text-align:center;">Card reader</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="500" width="251" src="'+a+'" style="width:50px;"></td></tr><tr><td style="text-align:center;">6</td><td style="text-align:center;">Waste cards<br>(4*4cm per piece)</td><td style="text-align:center;">12</td><td style="text-align:center;"><img loading="lazy" height="495" width="658" src="'+l+'" style="width:300px;"></td></tr><tr><td style="text-align:center;">7</td><td style="text-align:center;">Traffic sign cards<br>(6.5*6.5cm per piece)</td><td style="text-align:center;">5</td><td style="text-align:center;"><img loading="lazy" height="162" width="250" src="'+s+'"></td></tr><tr><td style="text-align:center;">8</td><td style="text-align:center;">Number cards<br>(6.5*6.5cm per piece)</td><td style="text-align:center;">5</td><td style="text-align:center;"><img loading="lazy" height="126" width="193" src="'+d+'"></td></tr><tr><td style="text-align:center;">9</td><td style="text-align:center;">Tags<br>(6.5*6.5cm per piece)</td><td style="text-align:center;">3</td><td style="text-align:center;"><img loading="lazy" height="300" width="912" src="'+o+'" style="width:180px;"></td></tr></tbody></table><p>(2) WonderMV Vision Module + Hinge Bracket Packing List</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>No.</strong></th><th style="text-align:center;">Component</th><th style="text-align:center;"><strong>Quantity</strong></th><th style="text-align:center;"><strong>Picture</strong></th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:center;">WonderMV vision module</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="78" width="115" src="'+e+'"></td></tr><tr><td style="text-align:center;">2</td><td style="text-align:center;">Type-C data cable (100cm)</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="221" width="1000" src="'+n+'" style="width:200px;"></td></tr><tr><td style="text-align:center;">3</td><td style="text-align:center;">4PIN wire (30cm)</td><td style="text-align:center;">2</td><td style="text-align:center;"><img loading="lazy" height="109" width="485" src="'+r+'" style="width:200px;"></td></tr><tr><td style="text-align:center;">4</td><td style="text-align:center;">32GB SD card</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="283" width="389" src="'+i+'" style="width:45px;"></td></tr><tr><td style="text-align:center;">5</td><td style="text-align:center;">Card reader</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="500" width="251" src="'+a+'" style="width:50px;"></td></tr><tr><td style="text-align:center;">6</td><td style="text-align:center;">Waste cards<br>(4*4cm per piece)</td><td style="text-align:center;">12</td><td style="text-align:center;"><img loading="lazy" height="495" width="658" src="'+l+'" style="width:300px;"></td></tr><tr><td style="text-align:center;">7</td><td style="text-align:center;">Traffic sign cards<br>(6.5*6.5cm per piece)</td><td style="text-align:center;">5</td><td style="text-align:center;"><img loading="lazy" height="162" width="250" src="'+s+'"></td></tr><tr><td style="text-align:center;">8</td><td style="text-align:center;">Number cards<br>(6.5*6.5cm per piece)</td><td style="text-align:center;">5</td><td style="text-align:center;"><img loading="lazy" height="126" width="193" src="'+d+'"></td></tr><tr><td style="text-align:center;">9</td><td style="text-align:center;">Tags<br>(6.5*6.5cm per piece)</td><td style="text-align:center;">3</td><td style="text-align:center;"><img loading="lazy" height="300" width="912" src="'+o+'" style="width:180px;"></td></tr><tr><td style="text-align:center;">10</td><td style="text-align:center;">Hinge bracket (optional)</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="347" width="607" src="'+f+'" style="width:180px;"></td></tr><tr><td style="text-align:center;">11</td><td style="text-align:center;">Screw (optional)</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="210" width="620" src="'+_+'" style="width:250px;"></td></tr></tbody></table><h2 id="_1-3-main-chip-introduction" tabindex="-1">1.3 Main Chip Introduction <a class="header-anchor" href="#_1-3-main-chip-introduction" aria-label="Permalink to &quot;1.3 Main Chip Introduction&quot;">​</a></h2><p><strong>1.3.1 What is the K210 chip?</strong></p><p>(1) K210 is a microcontroller unit (MCU) based on the RISC-V Reduced Instruction Set Computing (RISC) architecture. Among its many features, a standout is the internally developed neural network hardware accelerator called KPU, which enables high-performance convolutional neural network operations. In terms of AI computing for MCUs, the computational power of the K210 chip is quite impressive. According to the Canaan official website, the KPUcomputational power can reach 1 TFLOPS (tera floating-point operations per second). To put this into perspective, the latest Raspberry Pi 4B has a computational power of less than 0.1 TFLOPS, and the Jetson Nano, which emphasizes neural network processing, has 128 CUDA cores with a computational power of only 0.47 TFLOPS.</p><p>(2) In addition to the impressive computational power of the KPU, the K210 chip supports FPIOA (Field Programmable IO Array), allowing each peripheral to be flexibly mapped to any pin. This simplifies the issues of pin allocation and GPIO wiring for developers.</p><p>(3) The K210 chip internally features a dual-core CPU with a 64-bit RISC-V instruction set. Each core is equipped with an independent Floating-Point Unit (FPU), enabling individual floating-point operations.</p><p>(4) To better serve in machine vision and audition, the K210 chip comes with a built-in Convolutional Artificial Neural Network accelerator (KPU) for computational convolution, and an Audio Processing Unit (APU) for handling microphone arrays. These capabilities enable high-performance machine vision and auditory processing.</p><p>(5) Furthermore, K210 also incorporates a Fast Fourier Transform (FFT) accelerator for efficient complex FFT calculations.</p><p>(6) Despite its powerful performance, the K210 chip places a significant emphasis on security. It includes built-in AES and SHA256 algorithm accelerators, providing effective protection for user data security.</p><p>(7) Examining the attributes about MCU, the K210 chip boasts a rich set of peripheral units, including DVP, JTAG, OTP, FPIOA, GPIO, UART, SPI, RTC, I2S, I2C, WDT, TIMER, PWM. These peripherals play a significant role in practical applications, effectively meeting the requirements of most MCU peripherals.</p><p>(8) K210 also features high-performance, low-power SRAM with a total capacity of 8M, where 2M is dedicated to AI computations and 6M is allocated for programs. It includes a dedicated external FLASH interface to expand its storage capacity. The data transfer can leverage the powerful DMA, providing exceptional performance in terms of data throughput.</p><p>(9) The following is the architecture diagram of the K210 chip, provided for reference only. For detailed information, please refer to the K210 chip technical manual document in the path <a href="./Appendix.html">Appendix-&gt;Chip Data &amp; Technical Parameters &amp; AI Model Files-&gt;1. Chip Data-&gt;K210 Chip Data</a>.</p><p><strong>1.3.2 What is the RISC-V?</strong></p><img loading="lazy" height="565" width="591" src="'+I+'" class="common_img"><p>K210 is a MCU based on the RISC-V (Reduced Instruction Set Computing V) architecture. The <strong>&quot;V&quot;</strong> in RISC-V represents the fifth generation of reduced instruction set architectures, developed and improved by the University of California, Berkeley, following the enhancements of the previous four generations. The project began at the University of California, Berkeley, in 2010, and after a decade of continuous refinement with contributions from many contributors, the RISC-V instruction set has gradually gained prominence worldwide. It is anticipated that in the near future, there will be more and better RISC-V chips emerging. RISC-V is characterized by the following features:</p><p>(1) Fully Open Source: Any company can freely and openly use the RISC-V instruction set to manufacture and market their own chips without the need for hefty licensing fees. Moreover, they have the flexibility to extend the instruction set based on their specific requirements. The extensions made by a company do not need to be open, allowing for differentiated development.</p><p>(2) Simplicity in Architecture: Compared to mainstream X86 and ARM architectures, RISC-V is a brand new instruction set that does not need to maintain compatibility with older products. Consequently, it appears particularly concise, with the entire foundational RISC-V instruction set comprising just over 40 instructions. When including other modular extension instructions, the total remains only a few dozen.</p><p>(3) Easy to Port: Modern operating systems separate privileged instructions, which can only be executed by the operating system, from user-level instructions that can be invoked in user mode, ensuring the stability of the operating system. RISC-V provides both privileged and user-level instructions, along with detailed specifications for RISC-V privileged and user-level instructions. This facilitates developers in porting Linux and Unix systems to the RISC-V platform.</p><p>(4) Modular Design: The RISC-V architecture can be composed of different modules with distinct functionalities, allowing flexible utilization of module combinations. This modular approach enables the customization of an MCU according to specific requirements. For instance, in embedded scenarios with limited space and low power consumption, one can opt for the RV32IC instruction set combination, utilizing only machine mode to significantly reduce power consumption and physical size. On the other hand, for high-performance application and operating system scenarios, the RV32IMFDC instruction set can be chosen, employing both machine and user modes to achieve superior performance.</p><p>(5) Comprehensive Toolchain: For a CPU, a toolchain is akin to a screwdriver for a screw. Without the tool, the screw cannot be fastened, rendering the performance of the CPU ineffective. The toolchain serves as the window for software development to interact with the CPU. Without a toolchain, software developers would be unable to make the CPU function. Fortunately, due to the dedicated contributions of many contributors over the years, the RISC-V community has provided a complete toolchain. Moreover, the RISC-V Foundation maintains and supports this toolchain.</p><h2 id="_1-4-pin-description" tabindex="-1">1.4 Pin Description <a class="header-anchor" href="#_1-4-pin-description" aria-label="Permalink to &quot;1.4 Pin Description&quot;">​</a></h2><p><strong>1.4.1 Hardware I/O Port</strong></p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Hardware I/O ports refer to the physical hardware pin numbers on the chip.</p></section><img loading="lazy" height="785" width="805" src="'+w+'" class="common_img"><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Hardware IO</strong></th><th style="text-align:left;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;">IO_RST</td><td style="text-align:left;">Reset K210, connect hardware circuit.</td></tr><tr><td style="text-align:center;">IO_1</td><td style="text-align:left;">Not used</td></tr><tr><td style="text-align:center;">IO_2</td><td style="text-align:left;">Not used</td></tr><tr><td style="text-align:center;">IO_3</td><td style="text-align:left;">Not used</td></tr><tr><td style="text-align:center;">IO_4</td><td style="text-align:left;">ISP_TX, connected to Type-C transmit pin.</td></tr><tr><td style="text-align:center;">IO_5</td><td style="text-align:left;">ISP_RX, connected to Type-C receive pin.</td></tr><tr><td style="text-align:center;">IO_6</td><td style="text-align:left;">LCD_CS</td></tr><tr><td style="text-align:center;">IO_7</td><td style="text-align:left;">LCD_WR</td></tr><tr><td style="text-align:center;">IO_8</td><td style="text-align:left;">LCD_DC</td></tr><tr><td style="text-align:center;">IO_9</td><td style="text-align:left;">DVP_SIO_D, Camera IIC&#39;s SDA.</td></tr><tr><td style="text-align:center;">IO_10</td><td style="text-align:left;">DVP_SIO_C，Camera IIC&#39;s SCL.</td></tr><tr><td style="text-align:center;">IO_11</td><td style="text-align:left;">DVP_RESET</td></tr><tr><td style="text-align:center;">IO_12</td><td style="text-align:left;">DVP_VSYNC</td></tr><tr><td style="text-align:center;">IO_13</td><td style="text-align:left;">DVP_PWDN</td></tr><tr><td style="text-align:center;">IO_14</td><td style="text-align:left;">DVP_XCLK</td></tr><tr><td style="text-align:center;">IO_15</td><td style="text-align:left;">DVP_PCLK</td></tr><tr><td style="text-align:center;">IO_16</td><td style="text-align:left;">BOOT, connected to hardware circuit.</td></tr><tr><td style="text-align:center;">IO_17</td><td style="text-align:left;">DVP_HREF</td></tr><tr><td style="text-align:center;">IO_18</td><td style="text-align:left;">External IIC interface SCL</td></tr><tr><td style="text-align:center;">IO_19</td><td style="text-align:left;">External IIC interface SDA</td></tr><tr><td style="text-align:center;">IO_20</td><td style="text-align:left;">LCD_TE</td></tr><tr><td style="text-align:center;">IO_21</td><td style="text-align:left;">LCD_RST</td></tr><tr><td style="text-align:center;">IO_22</td><td style="text-align:left;">LCD_RD</td></tr><tr><td style="text-align:center;">IO_23</td><td style="text-align:left;">LCD_BL</td></tr><tr><td style="text-align:center;">IO_24</td><td style="text-align:left;">User LED</td></tr><tr><td style="text-align:center;">IO_25</td><td style="text-align:left;">LED fill light</td></tr><tr><td style="text-align:center;">IO_26</td><td style="text-align:left;">Button SW1</td></tr><tr><td style="text-align:center;">IO_27</td><td style="text-align:left;">External UART interface RXD</td></tr><tr><td style="text-align:center;">IO_28</td><td style="text-align:left;">External UART interface TXD</td></tr><tr><td style="text-align:center;">IO_29</td><td style="text-align:left;">TF_SCLK</td></tr><tr><td style="text-align:center;">IO_30</td><td style="text-align:left;">TF_MOSI</td></tr><tr><td style="text-align:center;">IO_31</td><td style="text-align:left;">TF_MISO</td></tr><tr><td style="text-align:center;">IO_32</td><td style="text-align:left;">TF_CS</td></tr><tr><td style="text-align:center;">IO_33</td><td style="text-align:left;">Not used</td></tr><tr><td style="text-align:center;">IO_34</td><td style="text-align:left;">Not used</td></tr><tr><td style="text-align:center;">IO_35</td><td style="text-align:left;">Not used</td></tr><tr><td style="text-align:center;">IO_36</td><td style="text-align:left;">Not used</td></tr><tr><td style="text-align:center;">IO_37</td><td style="text-align:left;">Not used</td></tr><tr><td style="text-align:center;">IO_38</td><td style="text-align:left;">Not used</td></tr><tr><td style="text-align:center;">IO_39</td><td style="text-align:left;">Not used</td></tr><tr><td style="text-align:center;">IO_40</td><td style="text-align:left;">Not used</td></tr><tr><td style="text-align:center;">IO_41</td><td style="text-align:left;">Touchscreen INT</td></tr><tr><td style="text-align:center;">IO_42</td><td style="text-align:left;">Not used</td></tr><tr><td style="text-align:center;">IO_43</td><td style="text-align:left;">Not used</td></tr><tr><td style="text-align:center;">IO_44</td><td style="text-align:left;">Not used</td></tr><tr><td style="text-align:center;">IO_45</td><td style="text-align:left;">Not used</td></tr><tr><td style="text-align:center;">IO_46</td><td style="text-align:left;">Touchscreen RST</td></tr><tr><td style="text-align:center;">IO_47</td><td style="text-align:left;">Button SW2</td></tr></tbody></table><img loading="lazy" height="128" width="456" src="'+b+'" class="common_img"><img loading="lazy" height="180" width="608" src="'+C+'" class="common_img"><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Fixed IO</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;">SPI0_D0</td><td style="text-align:center;">Connect LCD_D0 pin</td></tr><tr><td style="text-align:center;">SPI0_D1</td><td style="text-align:center;">Connect LCD_D1 pin</td></tr><tr><td style="text-align:center;">SPI0_D2</td><td style="text-align:center;">Connect LCD_D2 pin</td></tr><tr><td style="text-align:center;">SPI0_D3</td><td style="text-align:center;">Connect LCD_D2 pin</td></tr><tr><td style="text-align:center;">SPI0_D4</td><td style="text-align:center;">ConnectLCD_D4 pin</td></tr><tr><td style="text-align:center;">SPI0_D5</td><td style="text-align:center;">Connect LCD_D5 pin</td></tr><tr><td style="text-align:center;">SPI0_D6</td><td style="text-align:center;">Connect LCD_D6 pin</td></tr><tr><td style="text-align:center;">SPI0_D7</td><td style="text-align:center;">Connect LCD_D7 pin</td></tr><tr><td style="text-align:center;">DVP_D0</td><td style="text-align:center;">Connect camera D0</td></tr><tr><td style="text-align:center;">DVP_D1</td><td style="text-align:center;">Connect camera D1</td></tr><tr><td style="text-align:center;">DVP_D2</td><td style="text-align:center;">Connect camera D2</td></tr><tr><td style="text-align:center;">DVP_D3</td><td style="text-align:center;">Connect camera D3</td></tr><tr><td style="text-align:center;">DVP_D4</td><td style="text-align:center;">Connect camera D4</td></tr><tr><td style="text-align:center;">DVP_D5</td><td style="text-align:center;">Connect camera D5</td></tr><tr><td style="text-align:center;">DVP_D6</td><td style="text-align:center;">Connect camera D6</td></tr><tr><td style="text-align:center;">DVP_D7</td><td style="text-align:center;">Connect camera D7</td></tr></tbody></table><p><strong>1.4.2 Function Mapping</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Function Number</strong></th><th style="text-align:center;"><strong>Function</strong></th><th style="text-align:center;"><strong>Bind to Hardware I/O</strong></th></tr></thead><tbody><tr><td style="text-align:center;">GPIO0</td><td style="text-align:center;">Button SW1</td><td style="text-align:center;">IO_26</td></tr><tr><td style="text-align:center;">GPIO1</td><td style="text-align:center;">Button SW2</td><td style="text-align:center;">IO_47</td></tr><tr><td style="text-align:center;">GPIO2</td><td style="text-align:center;">Fill light</td><td style="text-align:center;">IO_25</td></tr><tr><td style="text-align:center;">GPIO3</td><td style="text-align:center;">User LED</td><td style="text-align:center;">IO_24</td></tr><tr><td style="text-align:center;">GPIOHS30</td><td style="text-align:center;">LCD_RST</td><td style="text-align:center;">IO_21</td></tr><tr><td style="text-align:center;">GPIOHS31</td><td style="text-align:center;">LCD_DC</td><td style="text-align:center;">IO_8</td></tr><tr><td style="text-align:center;">GPIOHS10</td><td style="text-align:center;">LCD_TE</td><td style="text-align:center;">IO_20</td></tr><tr><td style="text-align:center;">GPIOHS11</td><td style="text-align:center;">LCD_RD</td><td style="text-align:center;">IO_22</td></tr><tr><td style="text-align:center;">GPIOHS7</td><td style="text-align:center;">LCD_BL</td><td style="text-align:center;">IO_23</td></tr></tbody></table><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The K210 chip features FPIOA (Field-Programmable IO Array), which can be controlled through software. It allows the mapping (connection) of GPIOHS (High-Speed GPIO), GPIO, SPI, and other function number interfaces to designated physical I/O ports. If not configured, the I/O ports are connected to the default function numbers.</p></section><p><strong>1.4.3 Expansion Interface</strong></p><p>The K210 Vision Module provides two user expansion interfaces: one IIC interface and one UART interface.</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Interface</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;">IIC Interface</td><td style="text-align:center;">Can communicate with other devices through IIC.</td></tr><tr><td style="text-align:center;">UART Interface</td><td style="text-align:center;">Can communicate with other devices through URAT.</td></tr></tbody></table><img loading="lazy" height="714" width="1176" src="'+D+'" class="common_img" style="width:500px;"><h2 id="_1-5-hinge-bracket-installation-instruction" tabindex="-1">1.5 Hinge Bracket Installation Instruction <a class="header-anchor" href="#_1-5-hinge-bracket-installation-instruction" aria-label="Permalink to &quot;1.5 Hinge Bracket Installation Instruction&quot;">​</a></h2><p>The hinge bracket is as shown in the following picture:</p><img loading="lazy" height="472" width="550" src="'+P+'" class="common_img" style="width:550px;"><p>Before installing the hinge bracket, we need to remove the two M3x5 mechanical screws underneath the K210 Vision Module.</p><img loading="lazy" height="206" width="322" src="'+O+'" class="common_img" style="width:550px;"><p>Align the two M3 screw holes on the hinge bracket with the two screw holes on the K210 Vision Module. Securely attach the two previously removed M3x5 mechanical screws.</p><img loading="lazy" height="472" width="553" src="'+V+'" class="common_img" style="width:550px;"><img loading="lazy" height="586" width="517" src="'+S+'" class="common_img" style="width:550px;"><p>Next, install the bracket onto the robot by using the reserved holes beneath the hinge bracket. The reserved holes support both M3 and M4 screws.</p><img loading="lazy" height="583" width="516" src="'+M+'" class="common_img" style="width:550px;">',69)])])}const K=c(T,[["render",v]]);export{W as __pageData,K as default};
